import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';

const definition = (inputSchema: Record<string, unknown>): ToolDefinition => ({
  name: 'weather',
  description: 'gets the weather',
  inputSchema,
});

describe('ToolRegistry input-schema validation', () => {
  it('returns a rejection for missing and wrong-typed required input without invoking the executor or exposing the value', async () => {
    const registry = new ToolRegistry();
    let calls = 0;
    registry.register(
      definition({
        type: 'object',
        properties: {location: {type: 'string'}},
        required: ['location'],
      }),
      async () => {
        calls += 1;
        return 'executor ran';
      }
    );

    const missing = await registry.execute('weather', {});
    const wrongType = await registry.execute('weather', {location: 42});

    expect(missing.result).toMatch(/location.*required/i);
    expect(wrongType.result).toMatch(/location.*string/i);
    expect(wrongType.result).not.toContain('42');
    expect(calls).toBe(0);
  });

  it('passes valid input and unlisted properties through unchanged exactly once, while preserving unknown-tool errors', async () => {
    const registry = new ToolRegistry();
    const input = {location: 'Berlin', identifyingNote: 'private'};
    const received: Record<string, unknown>[] = [];
    registry.register(
      definition({
        type: 'object',
        properties: {location: {type: 'string'}},
        required: ['location'],
      }),
      async toolInput => {
        received.push(toolInput);
        return 'forecast';
      }
    );

    await expect(registry.execute('weather', input)).resolves.toEqual({result: 'forecast'});
    expect(received).toEqual([input]);
    await expect(registry.execute('missing', {})).rejects.toThrow('Unknown tool: missing');
  });

  it('compiles static schemas at registration and validates each function-sourced schema at its current call', async () => {
    const staticSchema: Record<string, unknown> = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    const registry = new ToolRegistry();
    registry.register(definition(staticSchema), async () => 'executor ran');
    staticSchema.required = ['city'];

    for (let attempt = 0; attempt < 10; attempt += 1) {
      await expect(registry.execute('weather', {location: 'Berlin'})).resolves.toEqual({result: 'executor ran'});
    }
    await expect(registry.execute('weather', {})).resolves.toMatchObject({
      result: expect.stringMatching(/location.*required/i),
    });

    let call = 0;
    registry.register(
      () => ({
        ...definition({
          type: 'object',
          properties: {[call === 0 ? 'location' : 'city']: {type: 'string'}},
          required: [call === 0 ? 'location' : 'city'],
        }),
      }),
      async () => {
        call += 1;
        return 'executor ran';
      }
    );

    await expect(registry.execute('weather', {location: 'Berlin'})).resolves.toEqual({result: 'executor ran'});
    await expect(registry.execute('weather', {location: 'Berlin'})).resolves.toMatchObject({
      result: expect.stringMatching(/city.*required/i),
    });
  });

  it('rejects an uncompilable schema during registration and names the tool', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(definition({type: 'object', required: 'location'}), async () => 'executor ran')
    ).toThrow(/weather/i);
  });
});
# Definition of Done

> `ToolRegistry.execute` looks a tool up, logs the input's key names, and calls the executor without ever checking the declared `inputSchema` (`src/orchestration/tools/registry.ts`).

**Strategy: `direct`** — `ToolRegistry.execute` is the real callable seam, and registered executors provide observable evidence of whether validation happened before execution. The acceptance tests exercise the registry directly without replacing production modules.

## Done when these pass

- [ ] **returns schema rejection without executing malformed input** — required and wrong-typed fields produce a `ToolResponse` naming the failing field and expected type, without exposing the offending value or invoking the executor
      `src/orchestration/tools/registry.acceptance.test.ts`

- [ ] **preserves valid tool input and unknown-tool behavior** — valid unknown properties reach the executor unchanged exactly once, while an unregistered name still throws the existing error
      `src/orchestration/tools/registry.acceptance.test.ts`

- [ ] **uses the correct schema compilation lifetime** — static schemas are compiled at registration, function-valued definitions are resolved per call, and an invalid schema is rejected at registration with the tool name
      `src/orchestration/tools/registry.acceptance.test.ts`

## Facets

- [ ] Make malformed required and wrong-typed input return a readable `ToolResponse` before executor invocation.
- [ ] Preserve valid input, including extra properties, without coercion or defaults.
- [ ] Compile static schemas at registration and resolve function-valued schemas for each call.
- [ ] Reject uncompilable schemas during registration and retain the unknown-tool throw.
- [ ] Update the validator dependency, documentation, specification, migration note, changelog, and required production doc comment after the behavior is implemented.

## Out of scope

- Tool output validation, authorization, retry/timeout/rate limiting, and changing the unknown-tool error into a model-visible result.
- Chat-loop integration and provider behavior beyond the registry contract.

